INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u06-l01','course-a1-foundations','rooms-and-furniture','Rooms and Furniture','Name rooms and common furniture and describe a home.','A1',26,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u06-l01-q01','a1-u06-l01','multiple_choice','Which room is usually used for cooking?','[{"id":"a","text":"bedroom"},{"id":"b","text":"kitchen"},{"id":"c","text":"bathroom"}]','b','A kitchen is used for cooking.',1),
('a1-u06-l01-q02','a1-u06-l01','multiple_choice','Choose the correct phrase.','[{"id":"a","text":"a sofa"},{"id":"b","text":"an sofa"},{"id":"c","text":"some sofa"}]','a','Sofa is a singular countable noun beginning with a consonant sound.',2),
('a1-u06-l01-q03','a1-u06-l01','multiple_choice','Where do you usually sleep?','[{"id":"a","text":"in a bed"},{"id":"b","text":"in a fridge"},{"id":"c","text":"at a desk"}]','a','People usually sleep in a bed.',3),
('a1-u06-l01-q04','a1-u06-l01','multiple_choice','Which item is furniture?','[{"id":"a","text":"wardrobe"},{"id":"b","text":"window"},{"id":"c","text":"garden"}]','a','A wardrobe is a piece of furniture.',4);
