INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u06-l04','course-a1-foundations','asking-for-and-giving-directions','Asking for and Giving Directions','Ask where a place is and understand simple directions.','A1',29,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u06-l04-q01','a1-u06-l04','multiple_choice','Choose a polite way to ask for directions.','[{"id":"a","text":"Excuse me, where is the bank?"},{"id":"b","text":"Give me bank."},{"id":"c","text":"You bank where?"}]','a','Excuse me is a polite way to begin a question.',1),
('a1-u06-l04-q02','a1-u06-l04','multiple_choice','What does ''turn left'' mean?','[{"id":"a","text":"Go to the left"},{"id":"b","text":"Go to the right"},{"id":"c","text":"Stop here"}]','a','Turn left means change direction to the left.',2),
('a1-u06-l04-q03','a1-u06-l04','multiple_choice','What should you do when someone says ''go straight''?','[{"id":"a","text":"Continue ahead"},{"id":"b","text":"Turn around"},{"id":"c","text":"Cross your arms"}]','a','Go straight means continue in the same direction.',3),
('a1-u06-l04-q04','a1-u06-l04','multiple_choice','Complete: The station is ___ the right.','[{"id":"a","text":"on"},{"id":"b","text":"at"},{"id":"c","text":"in"}]','a','The common phrase is on the right.',4);
